SELECT COUNT(*) FROM video_bounty_submission
WHERE campaign_id = #{campaignId} AND topic_id = #{topicId}
  AND status = 2 AND del_flag = '0'

SELECT * FROM video_bounty_submission
WHERE del_flag = '0'
AND campaign_id = #{campaignId}
AND status = #{status}
ORDER BY id DESC
LIMIT #{limit} OFFSET #{offset}
